{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not require IMDSv2, potentially allowing unauthorized access to instance metadata."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "Instance metadata service can be interacted with freely, potentially exposing sensitive information."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded secret in user data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The API key 'sk-1234567890abcdef' is hardcoded in the user data, potentially exposing it to unauthorized access."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Sensitive information exposure through environment variable",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The DATABASE_PASSWORD is being exported as an environment variable in the user data, potentially exposing it to unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"web_app\" {\n  name_prefix   = \"automated-employee-onboarding-platform-lt-web-\"\n  image_id      = data.aws_ami.ubuntu.id\n  instance_type = var.instance_type\n  key_name      = var.key_pair_name\n  vpc_security_group_ids = [aws_security_group.web_app.id]\n  user_data = base64encode(<<-EOF\n              apt-get update\n              apt-get install -y nginx nodejs npm\n              systemctl start nginx\n              systemctl enable nginx\n              EOF\n  )\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  tag_specifications {\n    resource_type = \"instance\"\n  }\n}",
  "fix_summary": "Enabled IMDSv2 by setting http_tokens to 'required' in metadata_options, and removed sensitive information from user data."
}
